// Generates src/components/atoms/Icon/icons.generated.ts from the Figma SVG snapshot.
//
//   src/components/atoms/Icon/figma/icons.json  Icon/* components, exported from Figma as SVG
//
// Run `npm run icons` after re-exporting. Never edit the generated file by hand.

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const iconDir = join(root, "src/components/atoms/Icon");
const { $source, icons } = JSON.parse(
  readFileSync(join(iconDir, "figma/icons.json"), "utf8"),
);

const attr = (tag, name) => tag.match(new RegExp(` ${name}="([^"]*)"`))?.[1];

const entries = Object.entries(icons).map(([name, { id, svg }]) => {
  const viewBox = attr(svg.match(/<svg[^>]*>/)[0], "viewBox");
  if (viewBox !== "0 0 24 24")
    throw new Error(`${name}: expected a 24×24 viewBox, got ${viewBox}`);
  const paths = [...svg.matchAll(/<path[^>]*\/>/g)].map(([tag]) => {
    if (!attr(tag, "stroke") || attr(tag, "fill"))
      throw new Error(`${name}: only stroked paths are supported`);
    // Every icon paints in one colour; the component uses currentColor so icons follow the text colour.
    return {
      d: attr(tag, "d"),
      strokeWidth: Number(attr(tag, "stroke-width")),
      ...(attr(tag, "stroke-linecap") && {
        strokeLinecap: attr(tag, "stroke-linecap"),
      }),
      ...(attr(tag, "stroke-linejoin") && {
        strokeLinejoin: attr(tag, "stroke-linejoin"),
      }),
    };
  });
  if (/<(?!svg|path|\/svg)\w+/.test(svg))
    throw new Error(`${name}: only <path> elements are supported`);
  return [name, { figmaId: id, paths }];
});

const out = `// GENERATED by scripts/generate-icons.mjs — do not edit.
// Source: Figma file ${$source.figmaFileKey}, Design system page ${$source.page} (Icon/*, Hugeicons).

export const icons = ${JSON.stringify(Object.fromEntries(entries), null, 2)} as const satisfies Record<
  string,
  {
    figmaId: string;
    paths: readonly { d: string; strokeWidth: number; strokeLinecap?: "round"; strokeLinejoin?: "round" }[];
  }
>;

export type IconName = keyof typeof icons;
`;

writeFileSync(join(iconDir, "icons.generated.ts"), out);
console.log(`icons: ${entries.length}`);
